 58→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 59→	logCtx := logging.WithComponent(ctx, "attach")
 60→
 61→	repoRoot, err := validateAttachPreconditions(ctx, sessionID)
 62→	if err != nil {
 63→		return err
 64→	}
 65→
 66→	ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName)
 67→	if err != nil {
 68→		return err
 69→	}
 70→	agentType := ag.Type()
 71→
 72→	transcriptData, err := ag.ReadTranscript(transcriptPath)
 73→	if err != nil {
 74→		return fmt.Errorf("failed to read transcript: %w", err)
 75→	}
 76→
 77→	relModifiedFiles, relNewFiles, relDeletedFiles, fileDetectionFailed := collectFileChanges(ctx, ag, transcriptPath, repoRoot)
 78→
 79→	if err := strategy.EnsureSetup(ctx); err != nil {
 80→		return fmt.Errorf("failed to set up strategy: %w", err)
 81→	}
 82→
 83→	logFile, sessionDir, sessionDirAbs, err := storeTranscript(ctx, sessionID, agentType, transcriptData)
 84→	if err != nil {
 85→		return err
 86→	}
 87→
 88→	author, err := GetGitAuthor(ctx)
 89→	if err != nil {
 90→		return fmt.Errorf("failed to get git author: %w", err)
 91→	}
 92→
 93→	meta := extractTranscriptMetadata(transcriptData)
 94→	firstPrompt := meta.FirstPrompt
 95→	commitMessage := generateCommitMessage(firstPrompt, agentType)
 96→
 97→	if firstPrompt != "" {
 98→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
 99→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
100→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
101→		}
102→	}
103→
104→	strat := GetStrategy(ctx)
105→	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
106→		return fmt.Errorf("failed to initialize session: %w", err)
107→	}
108→
109→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile, meta); err != nil {
110→		return err
111→	}
112→
113→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
114→	stepCtx := strategy.StepContext{
115→		SessionID:      sessionID,
116→		ModifiedFiles:  relModifiedFiles,
117→		NewFiles:       relNewFiles,
118→		DeletedFiles:   relDeletedFiles,
119→		MetadataDir:    sessionDir,
120→		MetadataDirAbs: sessionDirAbs,
121→		CommitMessage:  commitMessage,
122→		TranscriptPath: logFile,
123→		AuthorName:     author.Name,
124→		AuthorEmail:    author.Email,
125→		AgentType:      agentType,
126→	}
127→
128→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
129→		return fmt.Errorf("failed to save checkpoint: %w", err)
130→	}
131→
132→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
133→
134→	printAttachConfirmation(w, sessionID, totalChanges, fileDetectionFailed, condenseErr)
135→
136→	if checkpointIDStr != "" {
137→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
138→			logging.Warn(logCtx, "failed to amend commit", "error", err)
139→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
140→		}
141→	}
142→
143→	return nil
144→}
