146→// validateAttachPreconditions checks session ID format, git repo state, and duplicate sessions.
147→func validateAttachPreconditions(ctx context.Context, sessionID string) (string, error) {
148→	if err := validation.ValidateSessionID(sessionID); err != nil {
149→		return "", fmt.Errorf("invalid session ID: %w", err)
150→	}
151→
152→	repoRoot, err := paths.WorktreeRoot(ctx)
153→	if err != nil {
154→		return "", fmt.Errorf("not a git repository: %w", err)
155→	}
156→
157→	repo, repoErr := strategy.OpenRepository(ctx)
158→	if repoErr != nil {
159→		return "", fmt.Errorf("failed to open repository: %w", repoErr)
160→	}
161→	if strategy.IsEmptyRepository(repo) {
162→		return "", errors.New("repository has no commits yet — make an initial commit before running attach")
163→	}
164→
165→	store, err := session.NewStateStore(ctx)
166→	if err != nil {
167→		return "", fmt.Errorf("failed to open session store: %w", err)
168→	}
169→	existing, err := store.Load(ctx, sessionID)
170→	if err != nil {
171→		return "", fmt.Errorf("failed to check existing session: %w", err)
172→	}
173→	if existing != nil {
174→		return "", fmt.Errorf("session %s is already tracked by Entire", sessionID)
175→	}
176→
177→	return repoRoot, nil
178→}
