233→// storeTranscript creates the session metadata directory and writes the (optionally normalized) transcript.
234→func storeTranscript(ctx context.Context, sessionID string, agentType types.AgentType, transcriptData []byte) (logFile, sessionDir, sessionDirAbs string, err error) {
235→	logCtx := logging.WithComponent(ctx, "attach")
236→	sessionDir = paths.SessionMetadataDirFromSessionID(sessionID)
237→	sessionDirAbs, err = paths.AbsPath(ctx, sessionDir)
238→	if err != nil {
239→		return "", "", "", fmt.Errorf("failed to resolve session directory path: %w", err)
240→	}
241→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
242→		return "", "", "", fmt.Errorf("failed to create session directory: %w", err)
243→	}
244→
245→	storedTranscript := transcriptData
246→	if agentType == agent.AgentTypeGemini {
247→		if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
248→			storedTranscript = normalized
249→		} else {
250→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
251→		}
252→	}
253→
254→	logFile = filepath.Join(sessionDirAbs, paths.TranscriptFileName)
255→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
256→		return "", "", "", fmt.Errorf("failed to write transcript: %w", err)
257→	}
258→	return logFile, sessionDir, sessionDirAbs, nil
259→}
