371→	}
372→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
373→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
374→}
375→
376→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
377→// transcript resolution succeeds for the given session ID.
378→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
379→	for _, name := range agent.List() {
380→		if name == skip {
381→			continue
382→		}
383→		ag, err := agent.Get(name)
384→		if err != nil {
385→			continue
386→		}
387→		path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
388→		if resolveErr != nil {
389→			logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
390→			continue
391→		}
392→		return ag, path, nil
393→	}
394→	return nil, "", errors.New("transcript not found for any registered agent")
395→}
396→
397→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
398→// When force is true, it amends without prompting.
399→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
400→	// Get HEAD commit info
401→	repo, err := openRepository(ctx)
402→	if err != nil {
403→		return fmt.Errorf("failed to open repository: %w", err)
404→	}
405→	headRef, err := repo.Head()
406→	if err != nil {
407→		return fmt.Errorf("failed to get HEAD: %w", err)
408→	}
409→	headCommit, err := repo.CommitObject(headRef.Hash())
410→	if err != nil {
411→		return fmt.Errorf("failed to get HEAD commit: %w", err)
412→	}
413→
414→	shortHash := headRef.Hash().String()[:7]
415→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
416→
417→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
418→
419→	amend := true
420→	if !force {
421→		form := NewAccessibleForm(
422→			huh.NewGroup(
423→				huh.NewConfirm().
424→					Title("Amend the last commit in this branch?").
425→					Affirmative("Y").
426→					Negative("n").
427→					Value(&amend),
428→			),
429→		)
430→		if err := form.Run(); err != nil {
431→			return fmt.Errorf("prompt failed: %w", err)
432→		}
433→	}
434→
435→	if !amend {
436→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
437→		return nil
438→	}
439→
440→	// Skip amending if this exact checkpoint ID is already in the commit
441→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
442→		if existing.String() == checkpointIDStr {
443→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
444→			return nil
445→		}
446→	}
447→
448→	// Amend the commit with the checkpoint trailer.
449→	newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
450→
451→	// --only ensures this amend updates the commit message only and does not
452→	// accidentally include unrelated staged changes.
453→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
454→	if output, err := cmd.CombinedOutput(); err != nil {
455→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
456→	}
457→
458→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
459→	return nil
460→}
