 1→package cli
 2→
 3→import (
 4→	"bytes"
 5→	"encoding/json"
 6→	"time"
 7→
 8→	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
 9→	"github.com/entireio/cli/cmd/entire/cli/transcript"
10→)
11→
12→// transcriptMetadata holds metadata extracted from a single transcript parse pass.
13→type transcriptMetadata struct {
14→	FirstPrompt string
15→	TurnCount   int
16→	Model       string
17→}
18→
19→// extractTranscriptMetadata parses transcript bytes once and extracts the first user prompt,
20→// user turn count, and model name. Supports both JSONL (Claude Code, Cursor, OpenCode) and
21→// Gemini JSON format.
22→func extractTranscriptMetadata(data []byte) transcriptMetadata {
23→	var meta transcriptMetadata
24→
25→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
26→	lines, err := transcript.ParseFromBytes(data)
27→	if err == nil {
28→		for _, line := range lines {
29→			if line.Type == transcript.TypeUser {
30→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
31→					meta.TurnCount++
32→					if meta.FirstPrompt == "" {
33→						meta.FirstPrompt = prompt
34→					}
35→				}
36→			}
37→			if line.Type == transcript.TypeAssistant && meta.Model == "" {
38→				var msg struct {
39→					Model string `json:"model"`
40→				}
41→				if json.Unmarshal(line.Message, &msg) == nil && msg.Model != "" {
42→					meta.Model = msg.Model
43→				}
44→			}
45→		}
46→		if meta.TurnCount > 0 || meta.Model != "" {
47→			return meta
48→		}
49→	}
50→
51→	// Fallback: try Gemini JSON format {"messages": [...]}
52→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
53→		meta.FirstPrompt = prompts[0]
54→		meta.TurnCount = len(prompts)
55→	}
56→
57→	return meta
58→}
59→
60→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
61→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
62→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
63→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
64→func estimateSessionDuration(data []byte) int64 {
65→	type timestamped struct {
66→		Timestamp string `json:"timestamp"`
67→	}
68→
69→	var first, last time.Time
70→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
71→		if len(rawLine) == 0 {
72→			continue
73→		}
74→		var ts timestamped
75→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
76→			continue
77→		}
78→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
79→		if err != nil {
80→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
81→			if err != nil {
82→				continue
83→			}
84→		}
85→		if first.IsZero() {
86→			first = parsed
87→		}
88→		last = parsed
89→	}
90→
91→	if first.IsZero() || last.IsZero() || !last.After(first) {
92→		return 0
93→	}
94→	return last.Sub(first).Milliseconds()
95→}
