 19→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 20→// Computes the path dynamically from the current repo location for cross-machine portability.
 21→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 22→	repoRoot, err := paths.WorktreeRoot(ctx)
 23→	if err != nil {
 24→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 25→	}
 26→
 27→	sessionDir, err := agent.GetSessionDir(repoRoot)
 28→	if err != nil {
 29→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 30→	}
 31→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 32→}
 33→
 34→// searchTranscriptInProjectDirs searches for a session transcript across an agent's
 35→// project directories that could plausibly belong to the current repository.
 36→// Agents like Claude Code and Gemini CLI derive the project directory from the cwd,
 37→// so the transcript may be stored under a different project directory if the session
 38→// was started from a different working directory.
 39→//
 40→// The search is scoped to the agent's base directory (e.g., ~/.claude/projects) and only
 41→// walks immediate subdirectories (plus one extra level for agents like Gemini that nest
 42→// chats under <project>/chats/).
 43→// Only agents implementing SessionBaseDirProvider support this fallback search.
 44→func searchTranscriptInProjectDirs(sessionID string, ag agentpkg.Agent) (string, error) {
 45→	provider, ok := agentpkg.AsSessionBaseDirProvider(ag)
 46→	if !ok {
 47→		return "", fmt.Errorf("fallback transcript search not supported for agent %q", ag.Name())
 48→	}
 49→	baseDir, err := provider.GetSessionBaseDir()
 50→	if err != nil {
 51→		return "", fmt.Errorf("failed to get base directory: %w", err)
 52→	}
 53→
 54→	// Walk subdirectories with a max depth of 3 (baseDir/project/subdir/file)
 55→	// to avoid scanning unrelated project trees.
 56→	baseDirDepth := strings.Count(filepath.Clean(baseDir), string(filepath.Separator))
 57→	const maxExtraDepth = 3
 58→
 59→	var found string
 60→	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
 61→		if err != nil {
 62→			return nil //nolint:nilerr // skip inaccessible dirs
 63→		}
 64→		if !d.IsDir() {
 65→			return nil
 66→		}
 67→		// Limit walk depth
 68→		depth := strings.Count(filepath.Clean(path), string(filepath.Separator)) - baseDirDepth
 69→		if depth > maxExtraDepth {
 70→			return filepath.SkipDir
 71→		}
 72→		candidate := ag.ResolveSessionFile(path, sessionID)
 73→		if _, statErr := os.Stat(candidate); statErr == nil {
 74→			found = candidate
 75→			return filepath.SkipAll
 76→		}
 77→		return nil
 78→	})
 79→	if walkErr != nil {
 80→		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
 81→	}
 82→	if found != "" {
 83→		return found, nil
 84→	}
 85→	return "", errors.New("transcript not found in any project directory")
 86→}
