 95→// toolResultBlock represents a tool_result in a user message
 96→type toolResultBlock struct {
 97→	Type      string `json:"type"`
 98→	ToolUseID string `json:"tool_use_id"`
 99→}
100→
101→// userMessageWithToolResults represents a user message that may contain tool results
102→type userMessageWithToolResults struct {
103→	Content []toolResultBlock `json:"content"`
104→}
105→
106→// FindCheckpointUUID finds the UUID of the message containing the tool_result
107→// for the given tool_use_id. This is used to find the checkpoint point for
108→// transcript truncation when rewinding to a task.
109→// Returns the UUID and true if found, empty string and false otherwise.
110→func FindCheckpointUUID(lines []transcriptLine, toolUseID string) (string, bool) {
111→	for _, line := range lines {
112→		if line.Type != transcript.TypeUser {
113→			continue
114→		}
115→
116→		var msg userMessageWithToolResults
117→		if err := json.Unmarshal(line.Message, &msg); err != nil {
118→			continue
119→		}
120→
121→		for _, block := range msg.Content {
122→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
123→				return line.UUID, true
124→			}
125→		}
126→	}
127→	return "", false
128→}
129→
130→// TruncateTranscriptAtUUID returns transcript lines up to and including the
131→// line with the given UUID. If the UUID is not found or is empty, returns
132→// the entire transcript.
133→//
134→//nolint:revive // Exported for testing purposes
135→func TruncateTranscriptAtUUID(lines []transcriptLine, uuid string) []transcriptLine {
136→	if uuid == "" {
137→		return lines
138→	}
139→
140→	for i, line := range lines {
141→		if line.UUID == uuid {
142→			return lines[:i+1]
143→		}
144→	}
145→
146→	// UUID not found, return full transcript
147→	return lines
148→}
