174→// TranscriptPosition contains the position information for a transcript file.
175→type TranscriptPosition struct {
176→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
177→	LineCount int    // Total number of lines
178→}
179→
180→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
181→// Returns empty position if file doesn't exist or is empty.
182→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
183→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
184→	if path == "" {
185→		return TranscriptPosition{}, nil
186→	}
187→
188→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
189→	if err != nil {
190→		if os.IsNotExist(err) {
191→			return TranscriptPosition{}, nil
192→		}
193→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
194→	}
195→	defer func() { _ = file.Close() }()
196→
197→	var pos TranscriptPosition
198→	reader := bufio.NewReader(file)
199→
200→	for {
201→		lineBytes, err := reader.ReadBytes('\n')
202→		if err != nil && err != io.EOF {
203→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
204→		}
205→
206→		if len(lineBytes) == 0 {
207→			if err == io.EOF {
208→				break
209→			}
210→			continue
211→		}
212→
213→		pos.LineCount++
214→
215→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
216→		var line transcriptLine
217→		if err := json.Unmarshal(lineBytes, &line); err == nil {
218→			if line.UUID != "" {
219→				pos.LastUUID = line.UUID
220→			}
221→		}
222→
223→		if err == io.EOF {
224→			break
225→		}
226→	}
227→
228→	return pos, nil
229→}
