361→+func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
362→+	logCtx := logging.WithComponent(ctx, "attach")
363→+
364→+	repoRoot, err := validateAttachPreconditions(ctx, sessionID)
365→+	if err != nil {
366→+		return err
367→+	}
368→+
369→+	ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName)
370→+	if err != nil {
371→+		return err
372→+	}
373→+	agentType := ag.Type()
374→+
375→+	transcriptData, err := ag.ReadTranscript(transcriptPath)
376→+	if err != nil {
377→+		return fmt.Errorf("failed to read transcript: %w", err)
378→+	}
379→+
380→+	relModifiedFiles, relNewFiles, relDeletedFiles, fileDetectionFailed := collectFileChanges(ctx, ag, transcriptPath, repoRoot)
381→+
382→+	if err := strategy.EnsureSetup(ctx); err != nil {
383→+		return fmt.Errorf("failed to set up strategy: %w", err)
384→+	}
385→+
386→+	logFile, sessionDir, sessionDirAbs, err := storeTranscript(ctx, sessionID, agentType, transcriptData)
387→+	if err != nil {
388→+		return err
389→+	}
390→+
391→+	author, err := GetGitAuthor(ctx)
392→+	if err != nil {
393→+		return fmt.Errorf("failed to get git author: %w", err)
394→+	}
395→+
396→+	meta := extractTranscriptMetadata(transcriptData)
397→+	firstPrompt := meta.FirstPrompt
398→+	commitMessage := generateCommitMessage(firstPrompt, agentType)
399→+
400→+	if firstPrompt != "" {
401→+		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
402→+		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
403→+			logging.Warn(logCtx, "failed to write prompt file", "error", err)
404→+		}
405→+	}
406→+
407→+	strat := GetStrategy(ctx)
408→+	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
409→+		return fmt.Errorf("failed to initialize session: %w", err)
410→+	}
411→+
412→+	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile, meta); err != nil {
413→+		return err
414→+	}
415→+
416→+	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
417→+	stepCtx := strategy.StepContext{
418→+		SessionID:      sessionID,
419→+		ModifiedFiles:  relModifiedFiles,
420→+		NewFiles:       relNewFiles,
421→+		DeletedFiles:   relDeletedFiles,
422→+		MetadataDir:    sessionDir,
423→+		MetadataDirAbs: sessionDirAbs,
424→+		CommitMessage:  commitMessage,
425→+		TranscriptPath: logFile,
426→+		AuthorName:     author.Name,
427→+		AuthorEmail:    author.Email,
428→+		AgentType:      agentType,
429→+	}
430→+
431→+	if err := strat.SaveStep(ctx, stepCtx); err != nil {
432→+		return fmt.Errorf("failed to save checkpoint: %w", err)
433→+	}
434→+
435→+	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
436→+
437→+	printAttachConfirmation(w, sessionID, totalChanges, fileDetectionFailed, condenseErr)
438→+
439→+	if checkpointIDStr != "" {
440→+		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
441→+			logging.Warn(logCtx, "failed to amend commit", "error", err)
442→+			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
